  "ヘルプ・使い方": {
    "en": "Help and instructions",
    "ko": "도움말 및 사용법",
    "zh-TW": "說明與使用方式"
  },
  "ユーザー名（セッション用）」に仲間が分かる名前を入力し、「変更」を選びます。": {
    "en": "Enter a recognizable name in Session username, then select Change.",
    "ko": "'세션용 사용자 이름'에 동료가 알아볼 수 있는 이름을 입력하고 '변경'을 선택하세요.",
    "zh-TW": "在「合奏用使用者名稱」輸入夥伴認得的名稱，再選擇「變更」。"
  },
  "Key一括リセット」は検索の解除ではありません。登録済みの保存Keyも原曲の0へ戻るため、検索し直したいときは検索欄とジャンルを操作してください。": {
    "en": "Reset all keys does not clear search filters. It also resets saved keys to the original key (0). To search again, use the search box and genre filters.",
    "ko": "'키 일괄 초기화'는 검색 해제가 아닙니다. 저장된 키도 원곡의 0으로 바뀝니다. 다시 검색하려면 검색창과 장르 필터를 사용하세요.",
    "zh-TW": "批次重設調性」不會清除搜尋條件，且會將已儲存調性重設為原調 0。重新搜尋請操作搜尋欄與曲風篩選。"
  },
  "選択曲に適用」を選び、対象曲の設定を確認します。": {
    "en": "Select Apply to selected, then check the updated song settings.",
    "ko": "'선택한 곡에 적용'을 선택하고 곡의 설정을 확인하세요.",
    "zh-TW": "選擇「套用至所選歌曲」，再確認歌曲設定。"
  },
  "選択曲を削除」は自分のマイリストから削除します。全曲一覧の楽曲自体は削除されません。削除前に選択した曲を確認してください。": {
    "en": "Remove selected songs deletes them from My list only, not the song catalog. Check your selection before deleting.",
    "ko": "'선택한 곡 삭제'는 마이리스트에서만 삭제합니다. 전체 곡 데이터는 삭제되지 않습니다. 삭제 전에 선택한 곡을 확인하세요.",
    "zh-TW": "移除所選歌曲」只會從個人清單移除，不會刪除歌曲資料。刪除前請確認選取的曲目。"
  },
  "戻す」は演奏確定から予約、完了から演奏確定へ戻します。": {
    "en": "Move back returns confirmed songs to the queue and completed songs to confirmed.",
    "ko": "'되돌리기'는 연주 확정 곡을 예약으로, 완료 곡을 연주 확정으로 되돌립니다.",
    "zh-TW": "返回」會將確定演奏的歌曲移回預約，或將完成歌曲移回確定演奏。"
  },
  "URLをコピー」を選び、OBSのソースに「ブラウザ」を追加して、URL欄へ貼り付けます。": {
    "en": "Select Copy URL. Add a Browser source in OBS and paste into its URL field.",
    "ko": "'URL 복사'를 선택하고 OBS에 브라우저 소스를 추가한 뒤 URL 입력란에 붙여넣으세요.",
    "zh-TW": "選擇「複製網址」，在 OBS 新增瀏覽器來源，並貼入網址欄。"
  },
  "② CSS生成」→「③ CSSをコピー」の順に操作し、OBSのブラウザソースの「カスタムCSS」へ貼り付けます。": {
    "en": "Select ② Generate CSS → ③ Copy CSS, then paste into Custom CSS in the OBS Browser source.",
    "ko": "'② CSS 생성 → ③ CSS 복사' 순서로 누른 뒤 OBS 브라우저 소스의 사용자 지정 CSS에 붙여넣으세요.",
    "zh-TW": "依序選「② 產生 CSS → ③ 複製 CSS」，再貼入 OBS 瀏覽器來源的自訂 CSS。"
  },
  "フレンドコードで探す」に相手のコードを入力し、「検索」を選びます。": {
    "en": "Enter their code in Find by friend code, then select Search.",
    "ko": "'친구 코드로 찾기'에 상대방의 코드를 입력하고 검색하세요.",
    "zh-TW": "在「以好友代碼搜尋」輸入對方代碼，再選搜尋。"
  },
  "自分との共通曲のみ」にチェックすると、一緒に演奏できる曲を探せます。「お気に入りアーティスト」も確認できます。": {
    "en": "Check Common songs only to find songs you can play together. You can also view favorite artists.",
    "ko": "'나와 공통인 곡만'을 체크하면 함께 연주할 곡을 찾을 수 있습니다. 즐겨찾는 아티스트도 확인할 수 있습니다.",
    "zh-TW": "勾選「僅顯示共同歌曲」可找出能一起演奏的曲目，也能查看收藏的藝人。"
  },
  "全曲一覧への楽曲申請」と「自分のマイリストへの登録」は別の操作です。公開された後、演奏できる曲を自分のマイリストへ登録してください。": {
    "en": "Requesting a catalog entry and adding to My list are separate actions. Once published, add songs you can perform to your own list.",
    "ko": "전체 곡 등록 신청과 마이리스트 등록은 별개입니다. 공개된 후 연주할 곡을 자신의 마이리스트에 추가하세요.",
    "zh-TW": "申請加入曲庫與加入個人清單是不同操作。歌曲公開後，請再將會演奏的曲目加入個人清單。"
  },
  "全曲一覧」「マイリスト」「ルーム」など、使いたい項目を選びます。Googleログインの入口はメニューの下部にあります。": {
    "en": "Choose All songs, My list, Room, or another feature. Google sign-in is at the bottom of the menu.",
    "ko": "전체 곡·마이리스트·룸 등 원하는 항목을 선택하세요. Google 로그인은 메뉴 아래에 있습니다.",
    "zh-TW": "選擇所有歌曲、個人清單、房間等功能。Google 登入入口在選單底部。"
  },
  "設定」→「最新情報を再読み込み」を試し、通信状況を確認します。共同操作では参加者に同じルームへ入っているかも確認してください。": {
    "en": "Try Settings → Reload latest data and check your connection. When working together, check that everyone is in the same room.",
    "ko": "설정 → 최신 정보 새로고침을 시도하고 연결 상태를 확인하세요. 함께 조작할 때는 같은 룸에 있는지도 확인하세요.",
    "zh-TW": "嘗試「設定 → 重新載入最新資料」並檢查連線。共同操作時也請確認所有人都在同一房間。"
  },
  "① 確定」→「② CSS生成」→「③ CSSをコピー」を行い、OBSのブラウザソースのカスタムCSSへ貼り直します。URLが現在のルームのものかも確認してください。": {
    "en": "Use ① Apply → ② Generate CSS → ③ Copy CSS, then paste again into the OBS Browser source’s Custom CSS. Also check that the URL is for the current room.",
    "ko": "① 적용 → ② CSS 생성 → ③ CSS 복사를 실행하고 OBS 브라우저 소스의 사용자 지정 CSS에 다시 붙여넣으세요. URL이 현재 룸의 것인지도 확인하세요.",
    "zh-TW": "依序操作①確認、②產生 CSS、③複製 CSS，再貼回 OBS 瀏覽器來源的自訂 CSS。也請確認網址屬於目前房間。"
  },
